DECLARE
    v_name VARCHAR2(30) := 'Rahul';
    v_age NUMBER := 20;
BEGIN
    DBMS_OUTPUT.PUT_LINE('Name: ' || v_name);
    DBMS_OUTPUT.PUT_LINE('Age: ' || v_age);
END;
/

DECLARE
    num NUMBER := 15;
BEGIN
    IF MOD(num,2)=0 THEN
        DBMS_OUTPUT.PUT_LINE('Even Number');
    ELSE
        DBMS_OUTPUT.PUT_LINE('Odd Number');
    END IF;
END;
/

DECLARE
    marks NUMBER := 82;
BEGIN
    CASE
        WHEN marks>=90 THEN
            DBMS_OUTPUT.PUT_LINE('Grade A+');
        WHEN marks>=75 THEN
            DBMS_OUTPUT.PUT_LINE('Grade A');
        WHEN marks>=60 THEN
            DBMS_OUTPUT.PUT_LINE('Grade B');
        ELSE
            DBMS_OUTPUT.PUT_LINE('Grade C');
    END CASE;
END;
/

DECLARE
    i NUMBER := 1;
BEGIN
    LOOP
        DBMS_OUTPUT.PUT_LINE(i);
        i := i + 1;
        EXIT WHEN i > 5;
    END LOOP;
END;
/

DECLARE
    i NUMBER := 1;
BEGIN
    WHILE i <= 5 LOOP
        DBMS_OUTPUT.PUT_LINE(i);
        i := i + 1;
    END LOOP;
END;
/

BEGIN
    FOR i IN 1..10 LOOP
        DBMS_OUTPUT.PUT_LINE(i);
    END LOOP;
END;
/

DECLARE
    CURSOR emp_cursor IS
        SELECT EmpName FROM Employee;
    v_name Employee.EmpName%TYPE;
BEGIN
    OPEN emp_cursor;
    LOOP
        FETCH emp_cursor INTO v_name;
        EXIT WHEN emp_cursor%NOTFOUND;
        DBMS_OUTPUT.PUT_LINE(v_name);
    END LOOP;
    CLOSE emp_cursor;
END;
/

CREATE OR REPLACE PROCEDURE GetEmployee(
    p_id IN NUMBER
)
AS
    v_name Employee.EmpName%TYPE;
BEGIN
    SELECT EmpName INTO v_name
    FROM Employee
    WHERE EmpID = p_id;

    DBMS_OUTPUT.PUT_LINE('Employee Name: ' || v_name);
END;
