    initgraph(&gd,&gm,(char*)"");

    int x1=100,y1=100,x2=300,y2=200;
    float dx=x2-x1;
    float dy=y2-y1;
    int steps=(abs(dx)>abs(dy))?abs(dx):abs(dy);
    float xinc=dx/steps;
    float yinc=dy/steps;
    float x=x1,y=y1;

    for(int i=0;i<=steps;i++)
    {
        putpixel(round(x),round(y),WHITE);
        x+=xinc;
        y+=yinc;
    }

    getch();
    closegraph();
    return 0;
}

