#include<graphics.h>
#include<conio.h>

void drawCircle(int xc,int yc,int x,int y)
{
    putpixel(xc+x,yc+y,WHITE);
    putpixel(xc-x,yc+y,WHITE);
    putpixel(xc+x,yc-y,WHITE);
    putpixel(xc-x,yc-y,WHITE);
    putpixel(xc+y,yc+x,WHITE);
    putpixel(xc-y,yc+x,WHITE);
    putpixel(xc+y,yc-x,WHITE);
    putpixel(xc-y,yc-x,WHITE);
}

int main()
{
    int gd=DETECT,gm;
    initgraph(&gd,&gm,(char*)"");

    int xc=250,yc=200,r=80;
    int x=0,y=r;
    int p=1-r;

    while(x<=y)
    {
        drawCircle(xc,yc,x,y);
        x++;
        if(p<0)
            p+=2*x+1;
        else
        {
            y--;
            p+=2*(x-y)+1;
        }
    }

    getch();
    closegraph();
    return 0;
}

